CREATE DATABASE IF NOT EXISTS event_finder CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE event_finder;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role ENUM('USER','ORGANISER','ADMIN') NOT NULL DEFAULT 'USER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS events (id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,category_id BIGINT NOT NULL,event_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,venue VARCHAR(150) NOT NULL,location VARCHAR(150) NOT NULL,image_url VARCHAR(500),organiser_name VARCHAR(100),organiser_email VARCHAR(150),capacity INT NOT NULL CHECK(capacity>0),created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_event_category FOREIGN KEY(category_id) REFERENCES categories(id),CONSTRAINT fk_event_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS registrations (id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,status ENUM('CONFIRMED','CANCELLED') NOT NULL DEFAULT 'CONFIRMED',registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_event_user(event_id,user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
INSERT IGNORE INTO categories(name) VALUES ('Technology'),('Music'),('Business'),('Arts & Culture'),('Sports'),('Education'),('Food & Lifestyle'),('Community');
